    {% csrf_token %}
    {{ form.as_p }}
    <button type="submit">Add to cart</button>
</form>
{% else %}
<p>This product is currently unavailable.</p>
{% endif %}

<p><a href="{% url 'home' %}">Back to home</a></p>
{% endblock %}

{% extends "base.html" %}

{% block title %}Order History — Digital Cafe{% endblock %}

{% block content %}
<h2>Order History</h2>

{% if orders %}
{% for order in orders %}
<section>
    <h3>Order #{{ order.id }} — {{ order.created_at }}</h3>
    <ul>
        {% for line in order.orderline_set.all %}
        <li>{{ line.product_name }} — ${{ line.unit_price }} x {{ line.quantity }} = ${{ line.subtotal }}</li>
        {% endfor %}
    </ul>
    <p>Order total: ${{ order.total }}</p>
</section>
{% endfor %}
{% else %}
<p>You haven't placed any orders yet.</p>
{% endif %}

<p><a href="{% url 'home' %}">Back to home</a></p>
{% endblock %}

{% extends "base.html" %}

{% block title %}Log in — Digital Cafe{% endblock %}

{% block content %}
<h2>Log in</h2>
<form method="post">
    {% csrf_token %}
    {{ form.as_p }}
    <button type="submit">Log in</button>
</form>
{% endblock %}

