    {% if product.image %}
    <img class="product-media-large" src="{{ product.image.url }}" alt="{{ product.name }}">
    {% else %}
    {% include "cafe/_image_placeholder.html" with media_class="product-media-large" %}
    {% endif %}
    <h2>{{ product.name }}</h2>
    <p>{{ product.description }}</p>
    <p>Price: ${{ product.price }}</p>

    {% if product.is_active %}
    <form method="post" action="{% url 'add_to_cart' product.pk %}">
        {% csrf_token %}
        {{ form.as_p }}
        <button type="submit">Add to cart</button>
